// Seed A — Clean reference-style MUX-based synchronizer.
// Same architecture as RTLLM's verified implementation but fixes a latent
// bug there: the en_data_reg register (clocked by clk_a) used `!brstn`
// instead of `!arstn` for its reset. This version resets it with arstn.
module synchronizer(
    input            clk_a,
    input            clk_b,
    input            arstn,
    input            brstn,
    input      [3:0] data_in,
    input            data_en,
    output reg [3:0] dataout
);
    reg [3:0] data_reg;
    reg       en_data_reg;
    reg       en_clap_one;
    reg       en_clap_two;

    // Source (clk_a) domain
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) data_reg <= 4'd0;
        else        data_reg <= data_in;
    end

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) en_data_reg <= 1'b0;
        else        en_data_reg <= data_en;
    end

    // Destination (clk_b) domain: two-flop synchronizer on the enable.
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) en_clap_one <= 1'b0;
        else        en_clap_one <= en_data_reg;
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) en_clap_two <= 1'b0;
        else        en_clap_two <= en_clap_one;
    end

    // Output mux: capture data_reg when the synchronized enable is high,
    // otherwise hold the previous value.
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)             dataout <= 4'd0;
        else if (en_clap_two)   dataout <= data_reg;
        else                    dataout <= dataout;
    end
endmodule

// Seed B — Compact single-always-per-domain style.
// Same behaviour as the MUX synchronizer, but each clock domain is handled
// in exactly one always block; the two-flop sync chain is packed into a
// 2-bit shift register.
module synchronizer(
    input            clk_a,
    input            clk_b,
    input            arstn,
    input            brstn,
    input      [3:0] data_in,
    input            data_en,
    output reg [3:0] dataout
);
    reg [3:0] data_reg;
    reg       en_data_reg;
    reg [1:0] en_sync;   // {en_clap_two, en_clap_one}

    // Source domain: data path and enable capture share one always block.
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_reg    <= 4'd0;
            en_data_reg <= 1'b0;
        end else begin
            data_reg    <= data_in;
            en_data_reg <= data_en;
        end
    end

    // Destination domain: 2-flop sync of the enable and the output mux.
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_sync <= 2'b00;
            dataout <= 4'd0;
        end else begin
            en_sync <= {en_sync[0], en_data_reg};
            if (en_sync[1]) dataout <= data_reg;
        end
    end
endmodule

// Seed C — Gated-capture variant.
// Rather than muxing dataout every clk_b cycle, this version only clocks the
// output register when the synchronized enable is high. Functionally
// equivalent to the MUX synchronizer because an unclocked register holds its
// value. Often slightly lower switching activity (hence power).
module synchronizer(
    input            clk_a,
    input            clk_b,
    input            arstn,
    input            brstn,
    input      [3:0] data_in,
    input            data_en,
    output reg [3:0] dataout
);
    reg [3:0] data_reg;
    reg       en_data_reg;
    reg       en_clap_one;
    reg       en_clap_two;

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_reg    <= 4'd0;
            en_data_reg <= 1'b0;
        end else begin
            data_reg    <= data_in;
            en_data_reg <= data_en;
        end
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_clap_one <= 1'b0;
            en_clap_two <= 1'b0;
        end else begin
            en_clap_one <= en_data_reg;
            en_clap_two <= en_clap_one;
        end
    end

    // Separate output register — hold when en_clap_two is low.
    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)             dataout <= 4'd0;
        else if (en_clap_two)   dataout <= data_reg;
    end
endmodule

// Seed D — Parameterised sync-chain variant.
// Uses a localparam-sized shift register so the synchronizer depth can be
// tuned; defaults to depth 2 to match the spec. The output stage explicitly
// muxes between data_reg and the held dataout to mirror the RTLLM wording.
module synchronizer(
    input            clk_a,
    input            clk_b,
    input            arstn,
    input            brstn,
    input      [3:0] data_in,
    input            data_en,
    output reg [3:0] dataout
);
    localparam integer SYNC_DEPTH = 2;

    reg [3:0]            data_reg;
    reg                  en_data_reg;
    reg [SYNC_DEPTH-1:0] en_sync;

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) data_reg <= 4'd0;
        else        data_reg <= data_in;
    end

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) en_data_reg <= 1'b0;
        else        en_data_reg <= data_en;
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) en_sync <= {SYNC_DEPTH{1'b0}};
        else        en_sync <= {en_sync[SYNC_DEPTH-2:0], en_data_reg};
    end

    wire en_sync_final = en_sync[SYNC_DEPTH-1];

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)              dataout <= 4'd0;
        else                     dataout <= en_sync_final ? data_reg : dataout;
    end
endmodule
